script:
$env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
cd "$env:USERPROFILE\Desktop\audit2"
"=== testing opencode ==="
$job = Start-Job -ScriptBlock {
  $env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
  Set-Location "$env:USERPROFILE\Desktop\audit2"
  "test" | opencode run "Reply with exactly: SPACEBUNNY_OK" 2>&1
}
if (Wait-Job $job -Timeout 60) {
  $result = Receive-Job $job
  "Result: $result"
} else {
  "TIMED OUT after 60s"
  Stop-Job $job
}
Remove-Job $job -Force
"=== GITHUB_TOKEN check ==="
"Token set: " + (-not [string]::IsNullOrEmpty([Environment]::GetEnvironmentVariable("GITHUB_TOKEN", "User")))
